const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class TodoWorld extends World {
  constructor(parameters) {
    super(parameters);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.write(html);
    this.document.close();
  }

  get newTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  get todoList() {
    return this.document.querySelector('.todo-list');
  }

  get todoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  get todoCount() {
    return this.document.querySelector('.todo-count');
  }

  get mainSection() {
    return this.document.querySelector('.main');
  }

  get footer() {
    return this.document.querySelector('.footer');
  }

  get toggleAll() {
    return this.document.querySelector('.toggle-all');
  }

  get clearCompleted() {
    return this.document.querySelector('.clear-completed');
  }

  get filters() {
    return Array.from(this.document.querySelectorAll('.filters a'));
  }

  findTodoByText(text) {
    return this.todoItems.find(li => {
      const label = li.querySelector('label');
      return label && label.textContent === text;
    });
  }

  async addTodo(text) {
    this.newTodoInput.value = text;
    this.newTodoInput.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      bubbles: true,
    });
    this.newTodoInput.dispatchEvent(event);
  }

  async completeTodo(text) {
    const todo = this.findTodoByText(text);
    if (todo) {
      const checkbox = todo.querySelector('.toggle');
      checkbox.checked = true;
      checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    }
  }

  getSelectedFilter() {
    const selected = this.document.querySelector('.filters a.selected');
    return selected ? selected.textContent : null;
  }

  navigateTo(hash) {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
}

setWorldConstructor(TodoWorld);

module.exports = { TodoWorld };

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

Given('the TodoMVC app is loaded', async function () {
  await this.loadApp();
});

Given('the user has added a todo {string}', async function (text) {
  await this.addTodo(text);
});

Given('the user has added a completed todo {string}', async function (text) {
  await this.addTodo(text);
  await this.completeTodo(text);
});

Given('the user navigates to {string}', function (hash) {
  this.navigateTo(hash);
});

When('the user types {string} in the new todo input and presses Enter', async function (text) {
  await this.addTodo(text);
});

When('the user presses Enter with an empty input', async function () {
  await this.addTodo('');
});

When('the user clicks the checkbox on {string}', async function (text) {
  const todo = this.findTodoByText(text);
  const checkbox = todo.querySelector('.toggle');
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user clicks the destroy button on {string}', function (text) {
  const todo = this.findTodoByText(text);
  const destroyBtn = todo.querySelector('.destroy');
  destroyBtn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

When('the user double-clicks on {string}', function (text) {
  const todo = this.findTodoByText(text);
  const label = todo.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  const editingTodo = this.document.querySelector('.todo-list li.editing');
  const editInput = editingTodo.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    bubbles: true,
  });
  editInput.dispatchEvent(event);
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  const editingTodo = this.document.querySelector('.todo-list li.editing');
  const editInput = editingTodo.querySelector('.edit');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    bubbles: true,
  });
  editInput.dispatchEvent(event);
});

When('the user clears the edit input and presses Enter', function () {
  const editingTodo = this.document.querySelector('.todo-list li.editing');
  const editInput = editingTodo.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    bubbles: true,
  });
  editInput.dispatchEvent(event);
});

When('the user types {string} in the edit input', function (text) {
  const editingTodo = this.document.querySelector('.todo-list li.editing');
  const editInput = editingTodo.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user clicks outside the todo', function () {
  const editingTodo = this.document.querySelector('.todo-list li.editing');
  const editInput = editingTodo.querySelector('.edit');
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the page is reloaded', function () {
  const hash = this.window.location.hash;
  this.window.location.href = 'http://localhost/' + hash;
  this.window.dispatchEvent(new this.window.Event('load'));
});

When('the user navigates to {string}', function (hash) {
  this.navigateTo(hash);
});

When('the user clicks the toggle-all checkbox', function () {
  this.toggleAll.checked = !this.toggleAll.checked;
  this.toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user clicks the Clear completed button', function () {
  this.clearCompleted.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

Then('the todo list contains {string}', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(todo, `Expected todo list to contain "${text}"`);
});

Then('the todo list does not contain {string}', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(!todo, `Expected todo list not to contain "${text}"`);
});

Then('the todo list is empty', function () {
  assert.strictEqual(this.todoItems.length, 0, 'Expected todo list to be empty');
});

Then('the new todo input is empty', function () {
  assert.strictEqual(this.newTodoInput.value, '', 'Expected new todo input to be empty');
});

Then('the todo count shows {int} item(s) left', function (count) {
  const countText = this.todoCount.textContent;
  const expectedText = count === 1 ? '1 item left' : `${count} items left`;
  assert.ok(
    countText.includes(expectedText),
    `Expected todo count to show "${expectedText}" but got "${countText}"`
  );
});

Then('the todo {string} is completed', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(todo, `Expected todo "${text}" to exist`);
  assert.ok(todo.classList.contains('completed'), `Expected todo "${text}" to be completed`);
});

Then('the todo {string} is not completed', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(todo, `Expected todo "${text}" to exist`);
  assert.ok(!todo.classList.contains('completed'), `Expected todo "${text}" not to be completed`);
});

Then('the todo {string} has the completed class', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(todo, `Expected todo "${text}" to exist`);
  assert.ok(todo.classList.contains('completed'), `Expected todo "${text}" to have completed class`);
});

Then('the todo {string} is removed', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(!todo, `Expected todo "${text}" to be removed`);
});

Then('the todo {string} is in editing mode', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(todo, `Expected todo "${text}" to exist`);
  assert.ok(todo.classList.contains('editing'), `Expected todo "${text}" to be in editing mode`);
});

Then('the edit input contains {string}', function (text) {
  const editingTodo = this.document.querySelector('.todo-list li.editing');
  assert.ok(editingTodo, 'Expected a todo to be in editing mode');
  const editInput = editingTodo.querySelector('.edit');
  assert.strictEqual(editInput.value, text, `Expected edit input to contain "${text}"`);
});

Then('the {string} filter is selected', function (filterName) {
  const selected = this.getSelectedFilter();
  assert.strictEqual(selected, filterName, `Expected "${filterName}" filter to be selected`);
});

Then('the todo {string} is visible', function (text) {
  const todo = this.findTodoByText(text);
  assert.ok(todo, `Expected todo "${text}" to exist`);
  const style = this.window.getComputedStyle(todo);
  assert.notStrictEqual(style.display, 'none', `Expected todo "${text}" to be visible`);
});

Then('the todo {string} is not visible', function (text) {
  const todo = this.findTodoByText(text);
  if (todo) {
    const style = this.window.getComputedStyle(todo);
    assert.strictEqual(style.display, 'none', `Expected todo "${text}" not to be visible`);
  }
});

Then('all todos are completed', function () {
  const incomplete = this.todoItems.filter(li => !li.classList.contains('completed'));
  assert.strictEqual(incomplete.length, 0, 'Expected all todos to be completed');
});

Then('no todos are completed', function () {
  const completed = this.todoItems.filter(li => li.classList.contains('completed'));
  assert.strictEqual(completed.length, 0, 'Expected no todos to be completed');
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(this.toggleAll.checked, 'Expected toggle-all checkbox to be checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  assert.ok(!this.toggleAll.checked, 'Expected toggle-all checkbox to be unchecked');
});

Then('the main section is hidden', function () {
  const style = this.window.getComputedStyle(this.mainSection);
  assert.strictEqual(style.display, 'none', 'Expected main section to be hidden');
});

Then('the main section is visible', function () {
  const style = this.window.getComputedStyle(this.mainSection);
  assert.notStrictEqual(style.display, 'none', 'Expected main section to be visible');
});

Then('the footer is hidden', function () {
  const style = this.window.getComputedStyle(this.footer);
  assert.strictEqual(style.display, 'none', 'Expected footer to be hidden');
});

Then('the footer is visible', function () {
  const style = this.window.getComputedStyle(this.footer);
  assert.notStrictEqual(style.display, 'none', 'Expected footer to be visible');
});

Then('the Clear completed button is hidden', function () {
  const style = this.window.getComputedStyle(this.clearCompleted);
  assert.strictEqual(style.display, 'none', 'Expected Clear completed button to be hidden');
});

