(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shakedown';
  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var toggleAll = document.querySelector('.toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  var todos = loadTodos();

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function getRoute() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function render() {
    todoList.innerHTML = '';

    var route = getRoute();
    var filtered = todos.filter(function (todo) {
      if (route === 'active') return !todo.completed;
      if (route === 'completed') return todo.completed;
      return true;
    });

    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');

      var viewDiv = document.createElement('div');
      viewDiv.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.text;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      viewDiv.appendChild(checkbox);
      viewDiv.appendChild(label);
      viewDiv.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.text;

      li.appendChild(viewDiv);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.filter(function (t) { return t.completed; }).length;

    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item left' : 'items left');

    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }

    toggleAll.checked = todos.length > 0 && activeCount === 0;

    clearCompleted.style.display = completedCount === 0 ? 'none' : '';

    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
      var linkRoute = link.getAttribute('href');
      if (linkRoute === '#/' && route === 'all') link.classList.add('selected');
      if (linkRoute === '#/active' && route === 'active') link.classList.add('selected');
      if (linkRoute === '#/completed' && route === 'completed') link.classList.add('selected');
    });

    saveTodos(todos);
  }

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      var text = newTodoInput.value.trim();
      if (text) {
        todos.push({ id: generateId(), text: text, completed: false });
        newTodoInput.value = '';
        render();
      }
    }
  });

  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var li = e.target.closest('li');
      var id = li.dataset.id;
      var todo = todos.find(function (t) { return t.id === id; });
      if (todo) {
        todo.completed = e.target.checked;
        render();
      }
    }
  });

  todoList.addEventListener('click', function (e) {
    if (e.target.classList.contains('destroy')) {
      var li = e.target.closest('li');
      var id = li.dataset.id;
      todos = todos.filter(function (t) { return t.id !== id; });
      render();
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    if (e.target.tagName === 'LABEL') {
      var li = e.target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
    }
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.target.classList.contains('edit')) {
      if (e.key === 'Enter' || e.keyCode === 13) {
        var li = e.target.closest('li');
        var id = li.dataset.id;
        var text = e.target.value.trim();
        if (text) {
          var todo = todos.find(function (t) { return t.id === id; });
          if (todo) todo.text = text;
          render();
        } else {
          todos = todos.filter(function (t) { return t.id !== id; });
          render();
        }
      } else if (e.key === 'Escape' || e.keyCode === 27) {
        var li = e.target.closest('li');
        li.classList.remove('editing');
        var id = li.dataset.id;
        var todo = todos.find(function (t) { return t.id === id; });
        if (todo) e.target.value = todo.text;
      }
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      if (li && li.classList.contains('editing')) {
        var id = li.dataset.id;
        var text = e.target.value.trim();
        if (text) {
          var todo = todos.find(function (t) { return t.id === id; });
          if (todo) todo.text = text;
        }
        li.classList.remove('editing');
        render();
      }
    }
  }, true);

  toggleAll.addEventListener('change', function () {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    render();
  });

  clearCompleted.addEventListener('click', function () {
    todos = todos.filter(function (t) { return !t.completed; });
    render();
  });

  filterLinks.forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      window.location.hash = link.getAttribute('href');
    });
  });

  window.addEventListener('hashchange', function () {
    render();
  });

  render();
})();

edits.newText:
  function addTodoByText(text) {
    var trimmed = text.trim();
    if (trimmed) {
      todos.push({ id: generateId(), text: trimmed, completed: false });
      render();
    }
  }

  function completeTodoByText(text) {
    var todo = todos.find(function (t) { return t.text === text; });
    if (todo) {
      todo.completed = true;
      render();
    }
  }

  function toggleTodoByText(text) {
    var todo = todos.find(function (t) { return t.text === text; });
    if (todo) {
      todo.completed = !todo.completed;
      render();
    }
  }

  function deleteTodoByText(text) {
    todos = todos.filter(function (t) { return t.text !== text; });
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    render();
  }

  function editTodoByText(oldText, newText) {
    var todo = todos.find(function (t) { return t.text === oldText; });
    if (todo) {
      if (newText.trim()) {
        todo.text = newText.trim();
      } else {
        todos = todos.filter(function (t) { return t !== todo; });
      }
      render();
    }
  }

  window.__todoApp = {
    addTodo: addTodoByText,
    completeTodo: completeTodoByText,
    toggleTodo: toggleTodoByText,
    deleteTodo: deleteTodoByText,
    toggleAll: toggleAllTodos,
    clearCompleted: clearCompletedTodos,
    editTodo: editTodoByText,
    getTodos: function() { return todos; }
  };

  render();
})();

